    events.forEach((event) => {
        if (event.eventType === EVENT_TYPES.DELETE) {
            state = deleteLinks(state, shareId, [event.encryptedLink.linkId]);
        } else {
            state = addOrUpdate(state, shareId, [{ encrypted: event.encryptedLink }]);
        }
    });

    return state;
